#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

// Custom counting semaphore with mutex and condition
typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} semaphore_t;

// Initialize semaphore
void sem_init(semaphore_t *s, int value) {
    s->count = value;
    pthread_mutex_init(&s->mutex, NULL);
    pthread_cond_init(&s->cond, NULL);
}

// Wait operation: decrements count, blocks if negative
void sem_wait(semaphore_t *s) {
    pthread_mutex_lock(&s->mutex);
    while (s->count <= 0) {
        pthread_cond_wait(&s->cond, &s->mutex);
    }
    s->count--;
    pthread_mutex_unlock(&s->-than->mutex);
}

// Post operation: increments count, wakes one waiting thread
void sem_post(semaphore_t *s) {
    pthread_mutex_lock(&s->mutex);
    s->count++;
    pthread_cond_signal(&s->cond);
    pthread_mutex_unlock(&s->mutex);
}

// Destroy semaphore
void sem_destroy(semaphore_t *s) {
    pthread_mutex_destroy(&s->mutex);
    pthread_cond_destroy(&s->cond);
}

// Worker thread function
void* worker(void *arg) {
    semaphore_t *s = (semaphore_t*)arg;
    int id = *(int*)arg;

    // Each worker waits 3 times, then posts once
    for (int i = 0; i < 3; i++) {
        sem_wait(s);
        printf("Worker %d: waited, count now %d\n", id, s->count);
    }

    sem_post(s);
    printf("Worker %d: posted, count now %d\n", id, s->count);

    return NULL;
}

int main() {
    semaphore_t s;
    sem_init(&s, 0); // Initially 0

    pthread_t threads[3];
    int ids[3] = {0, 1, 2};

    // Create 3 worker threads
    for (int i = 0; i < 3; i++) {
        if (pthread_create(&threads[i], NULL, worker, &ids[i])) {
            perror("pthread_create");
            exit(1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    sem_destroy(&s);

    printf("All workers done.\n");
    return 0;
}
```

