```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <stdint.h>

// Custom counting semaphore structure
typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} custom_sem_t;

// Initialize a custom semaphore
void custom_sem_init(custom_sem_t *sem, int initial_count) {
    sem->count = initial_count;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

// Wait on the semaphore (blocks until count > 0)
int custom_sem_wait(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->count == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);
    return -1; // Wait succeeded, return -1 (convention for success)
}

// Non-blocking trywait: returns 0 if acquired, -1 if not
int custom_sem_trywait(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    int result = (sem->count > 0) ? 0 : -1;
    if (result == 0) {
        sem->count--;
    }
    pthread_mutex_unlock(&sem->mutex);
    return result;
}

// Signal: increment count and wake one waiting thread
void custom_sem_signal(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

// Destroy the semaphore
void custom_sem_destroy(custom_sem_t *sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

// Worker thread function: tests wait and trywait
void* worker_test(void *arg) {
    custom_sem_t *sem = (custom_sem_t*)arg;
    int id = *(int*)arg + 1; // 1 or 2

    printf("Worker %d: Starting test\n", id);

    // Test wait: wait until count > 0
    int result = custom_sem_wait(sem);
    printf("Worker %d: Wait completed, result = %d\n", id, result);

    // Test trywait: try to acquire when count is 0
    result = custom_sem_trywait(sem);
    printf("Worker %d: trywait result = %d\n", id, result);

    pthread_exit(NULL);
}

int main() {
    custom_sem_t sem;
    custom_sem_init(&sem, 1); // Start with count = 1

    pthread_t t1, t2;
    int id1 = 1, id2 = 2;

    // Start two worker threads
    pthread_create(&t1, NULL, worker_test, &id1);
    pthread_create(&t2, NULL, worker_test, &id2);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    // Signal to increment count (simulate after work)
    custom_sem_signal(&sem);
    custom_sem_destroy(&sem);

    printf("All workers done.\n");
    return 0;
}
```

