#define NUM_O 3

sem_t h_count;      // limits H threads to 2
sem_t o_count;      // limits O threads to 1
sem_t mutex;        // mutual exclusion for shared state
int molecules = 0;  // number of H2O molecules formed

void* hydrogen(void* arg) {
    int id = *(int*)arg;
    printf("H%d: entering critical section\n", id);

    // Wait until there are at most 2 H threads
    sem_wait(&h_count);

    // Mutual exclusion: only one thread can be in the critical section at a time
    sem_wait(&mutex);

    // Only proceed if we can form a valid H2O with one O
    if (molecules == 0 || molecules %  2 == 0) {
        // We can form a molecule with one O
        molecules++;
        printf("H%d: formed H2O molecule (molecules=%d)\n", id, molecules);
    } else {
        // If we already have 2 H and 1 O, we cannot form another
        // So we just exit without forming a molecule
        printf("H%d: no more molecules to form\n", id);
    }

    sem_post(&mutex);

    // Release the H count (we are done with this H thread)
    sem_post(&h_count);

    return NULL;
}

