    printf("O%d: entering critical section\n", id);

    // Wait until there is at most 1 O thread
    sem_wait(&o_count);

    sem_wait(&mutex);

    // Only form a molecule if we have exactly 2 H threads
    if (molecules == 0 || molecules % 2 == 0) {
        molecules++;
        printf("O%d: formed H2O molecule (molecules=%d)\n", id, molecules);
