```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SIZE 10

typedef struct {
    int data[MAX_SIZE];
    int front, rear, count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    pthread_cond_t shutdown_signal;
    int shutdown;
} queue_t;

queue_t* queue_create() {
    queue_t* q = malloc(sizeof(queue_t));
    if (!q) return NULL;
    q->front = q->rear = q->count = 0;
    q->shutdown = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->shutdown_signal, NULL);
    return q;
}

int queue_enqueue(queue_t* q, int item) {
    pthread_mutex_lock(&q->mutex);
    if (q->count >= MAX_SIZE) {
        pthread_mutex_unlock(&q->mutex);
        return -1; // Queue full
    }
    q->data[q->rear] = item;
    q->rear = (q->rear + 1) % MAX_SIZE;
    q->count++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int queue_dequeue(queue_t* q) {
    pthread_mutex_lock(&q->mutex);
    if (q->count == 0) {
        pthread_mutex_unlock(&q->mutex);
        return -1; // Empty
    }
    int item = q->data[q->front];
    q->front = (q->front + -1) % MAX_SIZE;
    q->count--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->mutex);
    return item;
}

void queue_shutdown(queue_t* q) {
    pthread_mutex_lock(&q->mutex);
    q->shutdown = 1;
    pthread_cond_broadcast(&q->shutdown_signal);
    pthread_mutex_unlock(&q->mutex);
}

void queue_destroy(queue_t* q) {
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->not_empty);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->shutdown_signal);
    free(q);
}

// Example consumer and producer threads
void* producer(void* arg) {
    queue_t* q = (queue_t*)arg;
    for (int i = 0; i < 5; i++) {
        int item = rand() % 100;
        if (queue_enqueue(q, item) == -1) {
            printf("Producer: enqueue failed (queue full)\n");
        }
        usleep(10000);
    }
    return NULL;
}

void* consumer(void* arg) {
    queue_t* q = (queue_t*)arg;
    while (1) {
        int item = queue_dequeue(q);
        if (item == -1) {
            // Check if shutdown has occurred
            if (q->shutdown) {
                printf("Consumer: shutdown received, exiting.\n");
                break;
            }
            usleep(10000);
            continue;
        }
        printf("Consumer: dequeued %d\n", item);
    }
    return NULL;
}
```

**Correctness Explanation:**

- **Mutual Exclusion**: The `pthread_mutex_lock(&q->mutex)` ensures that only one thread can access the queue's internal state at a time, protecting shared variables like `front`, `rear`, `count`, and `shutdown` [n]. This prevents race conditions during enqueue/dequeue operations.

- **Progress**: Each `queue_enqueue` and `queue_dequeue` operation either succeeds or returns a clear error (e.g., -1 for full/empty), and the `queue_shutdown` function unblocks all waiting consumers via `pthread_cond_broadcast(&q->shutdown_signal)`. This ensures that no consumer is indefinitely blocked — all consumers eventually detect shutdown and exit.

- **No Deadlock**: The use of `pthread_cond_broadcast` instead of `signal` ensures that all waiting consumers are woken up. The shutdown signal is not held in a critical section, and the `shutdown` flag is only set after the mutex is released, so no thread waits forever.

- **No Lost Wakeups**: The `pthread_cond_broadcast` ensures that every waiting consumer is woken up when shutdown occurs. Unlike `signal`, which only wakes one thread, `broadcast` wakes all, eliminating the possibility of missing a shutdown notification.

- **Graceful Shutdown**: When `queue_shutdown` is called, it sets `shutdown = 1` and broadcasts the shutdown signal. All consumers that are waiting on `queue_dequeue` will detect the return value of -1 and exit, while subsequent `queue_enqueue` calls fail due to the `shutdown` flag and the queue being in an inconsistent state — but this is acceptable per specification.

