```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 5
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 2

int buffer[BUFFER_SIZE];
int in = 0, out = 0;

sem_t slots;      // available slots (max slots - items in buffer)
sem_t items;      // items in buffer
pthread_mutex_t mutex; // for mutual exclusion on buffer access

void* producer(void *arg) {
    int id = *(int*)arg;
    int data = id * 100; // unique data per producer

    for (int i = 0; i < 10; i++) {
        // Wait for a slot
        sem_wait(&slots);
        // Critical section: access buffer
        pthread_mutex_lock(&mutex);
        buffer[in] = data;
        in = (in + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&mutex);
        // Signal that an item is now available
        sem_post(&items);
        printf("Producer %d produced %d\n", id, data);
    }
    return NULL;
}

void* consumer(void *arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 10; i++) {
        // Wait for an item
        sem_wait(&items);
        // Critical section: access buffer
        pthread_mutex_lock(&mutex);
        int data = buffer[out];
        out = (out +  1) % BUFFER_SIZE;
        pthread_mutex_unlock(&mutex);
        // Signal that a slot is now free
        sem_post(&slots);
        printf("Consumer %d consumed %d\n", id, data);
    }
    return NULL;
}

int main() {
    pthread_t producers[NUM_PRODUCERS];
    pthread_t consumers[NUM_CONSUMERS];

    // Initialize semaphores
    sem_init(&slots, 0, BUFFER_SIZE);
    sem_init(&items, 0, 0);
    pthread_mutex_init(&mutex, NULL);

    // Start producers
    for (int i = 0; i < NUM_PRODUCERS; i++) {
        int *id = malloc(sizeof(int));
        *id = i;
        pthread_create(&producers[i], NULL, producer, id);
    }

    // Start consumers
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        int *id = malloc(sizeof(int));
        *id = i;
        pthread_create(&consumers[i], NULL, consumer, id);
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_join(producers[i], NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_join(consumers[i], NULL);
    }

    // Cleanup
    sem_destroy(&slots);
    sem_destroy(&items);
    pthread_mutex_destroy(&mutex);

    printf("All producers and consumers finished.\n");
    return 0;
}
```

---

**Correctness Explanation:**

- **Mutual Exclusion**: The `mutex` protects access to the buffer array during both reading and writing. Only one thread can access the buffer at a time [n], ensuring no race condition on `in` and `out` indices.
