```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define BUFFER_SIZE 10
#define BATCH_SIZE 2

int buffer[BUFFER_SIZE];
int in = 0, out = 0;
int count = 0;

sem_t mutex;        // protects buffer access
sem_t space;        // available slots (initially BUFFER_SIZE)
sem_t item;         // items in buffer (initially 0)

void* producer(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 5; i++) {
        // Wait for BATCH_SIZE slots
        sem_wait(&space);
        sem_wait(&space);

        // Critical section: insert batch of BATCH_SIZE
        for (int j = 0; j < BATCH_SIZE; j++) {
            buffer[in] = id * 100 + i *  10 + j;
            in = (in + 1) % BUFFER_SIZE;
        }
        count += BATCH_SIZE;

        // Signal that items are now available
        sem_post(&item);
        sem_post(&item);

        printf("Producer %d inserted batch: %d, %d\n", id, buffer[(in - BATCH_SIZE) % BUFFER_SIZE], buffer[(in - BATCH_SIZE + 1) % BUFFER_SIZE]);
        sleep(1);
    }
    return NULL;
}

void* consumer(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 10; i++) {
        // Wait for an item
        sem_wait(&item);
        sem_wait(&item);

        // Critical section: remove one item
        int val = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count -= 1;

        printf("Consumer %d consumed: %d\n", id, val);
        sleep(1);
    }
    return NULL;
}

int main() {
    pthread_t prod[2], cons[2];

    // Initialize semaphores
    sem_init(&mutex, 0, 1);
    sem_init(&space, 0, BUFFER_SIZE);
    sem_init(&item, 0, 0);

    // Start producers
    for (int i = 0; i < 2; i++) {
        pthread_create(&prod[i], NULL, producer, &i);
    }

    // Start consumers
    for (int i = 0; i < 2; i++) {
        pthread_create(&cons[i], NULL, consumer, &i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 2; i++) {
        pthread_join(prod[i], NULL);
        pthread_join(cons[i], NULL);
    }

    // Cleanup
    sem_destroy(&mutex);
    sem_destroy(&space);
    sem_destroy(&item);

    printf("All operations complete.\n");
    return 0;
}
```

