```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 5
#define POISON_PILL -1

int buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int count = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t full_cond = PTHREAD_COND_INITIALIZER;
pthread_cond_t empty_cond = PTHREAD_COND_INITIALIZER;

void* producer(void* arg) {
    int id = *(int*)arg;
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(&mutex);
        while ((buffer_tail + 1) % BUFFER_SIZE == buffer_head) {
            pthread_cond_wait(&empty_cond, &mutex);
        }
        buffer[buffer_tail] = id * 10 + i;
        buffer_tail = (buffer_tail +  1) % BUFFER_SIZE;
        count++;
        pthread_cond_signal(&full_cond);
        pthread_mutex_unlock(&mutex);
        usleep(1000); // Simulate work
    }
    // Producer completes: inject poison pill
    pthread_mutex_lock(&mutex);
    buffer[buffer_tail] = POISON_PILL;
    buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    pthread_cond_broadcast(&empty_cond);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* consumer(void* arg) {
    int id = *(int*)arg;
    while (1) {
        pthread_mutex_lock(&mutex);
        while (buffer_head == buffer_tail) {
            pthread_cond_wait(&full_cond, &mutex);
        }
        int item = buffer[buffer_head];
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&mutex);

        if (item == POISON_PILL) {
            printf("Consumer %d: received poison pill, exiting.\n", id);
            return NULL;
        }
        printf("Consumer %d: consumed %d\n", id, item);
        usleep(1000);
    }
    return NULL;
}

