```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <time.h>

#define NUM_CUSTOMERS 10

// Shared state
sem_t customer_ready;
sem_t barber_sleeping;
sem_t mutex;
int closing = 0;
int customer_count = 0;

// Barber thread function
void* barber(void* arg) {
    printf("Barber is now awake and ready.\n");
    while (1) {
        // Wait for a customer to arrive
        sem_wait(&customer_ready);

        // Check if closing is signaled
        if (closing) {
            printf("Closing signal received. Barber is finishing current customer.\n");
            // If closing, we just exit after serving current customer
            // So we don't re-enter the loop
            break;
        }

        // Simulate serving a customer
        printf("Barber is serving a customer.\n");
        sleep(1); // Simulate service time

        // After serving, allow next customer to enter
        sem_post(&barber_sleeping);
    }

    printf("Barber is shutting down cleanly.\n");
    return NULL;
}

// Customer thread function
void* customer(void* arg) {
    int id = *(int*)arg;
    printf("Customer %d arriving.\n", id);

    // If closing is set, don't wait — just exit
    if (closing) {
        printf("Customer %d: Closing signal received. Exiting.\n", id);
        return NULL;
    }

    // Wait for barber to be ready
    sem_wait(&customer_ready);

    // If closing, exit
    if (closing) {
        printf("Customer %d: Closing signal received. Exiting.\n", id);
        return NULL;
    }

    // Simulate sitting in chair
    printf("Customer %d is now in chair.\n", id);
    sleep(1); // Simulate waiting

    // After sitting, barber will serve
    sem_wait(&barber_sleeping);

    printf("Customer %d is being served.\n");
    sleep( 1 ); // Simulate service

    printf("Customer %d is done.\n", id);
    return NULL;
