#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <assert.h>

// Shared counter and spinlock
atomic_int counter = 0;
atomic_int lock = 0; // 0 = free, 1 = held

// Function to acquire the spinlock
static inline void acquire_lock() {
    while (__atomic_test_and_set(&lock, __ATOMIC_ACQUIRE)) {
        // Spin until lock is released
    }
}

// Function to release the spinlock
static inline void release_lock() {
    __atomic_clear(&lock, __ATOMIC_RELEASE);
}

// Thread function: increment counter with spinlock
void* increment_counter(void* arg) {
    int tid = *(int*)arg;
    for (int i = 0; i < 1000; i++) {
        acquire_lock();
        counter++;
        release_lock();
    }
    return NULL;
}

int main() {
    int num_threads = 4;
    int thread_ids[num_threads];
    pthread_t threads[num_threads];
    int result;

    // Initialize thread IDs
    for (int i = 0; i < num_threads; i++) {
        thread_ids[i] = i;
    }

    // Create threads
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, increment_counter, &thread_ids[i]);
    }

    // Wait for all threads to complete
    for (int i =  0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Final value should be num_threads * 1000
    result = atomic_load(&counter);
    printf("Final counter value: %d\n", result);
    assert(result == num_threads * 1000);

    printf("Test passed: no race condition, mutual exclusion achieved.\n");
    return 0;
}
