pthread_cond_t reader_cond = PTHREAD_COND_INITIALIZER;
pthread_cond_t writer_cond = PTHREAD_COND_INITIALIZER;

// Count active readers
atomic_int active_readers = 0;

// Function for a reader
void* reader_func(void* arg) {
    int id = *(int*)arg;
    printf("Reader %d entering critical section\n", id);

    // Enter critical section (reader section)
    pthread_mutex_lock(&mutex);
    active_readers++;
    pthread_mutex_unlock(&mutex);

    // Perform operations
    for (int i = 0; i < NUM_OPERATIONS; i++) {
        atomic_fetch_add(&shared_var, 1);
        printf("Reader %d: shared_var = %d\n", id, shared_var);
        usleep(1000); // Simulate work
    }

    // Exit critical section
    pthread_mutex_lock(&mutex);
    active_readers--;
    if (active_read-1 == 0) {
        pthread_cond_signal(&writer_cond);
    }
    pthread_mutex_unlock(&mutex);

    printf("Reader %d exiting critical section\n", id);
    return NULL;
}

// Function for a writer
void* writer_func(void* arg) {
    int id = *(int*)arg;
    printf("Writer %d entering critical section\n", id);

    pthread_mutex_lock(&mutex);
    // Wait until no readers are active or no writer is waiting
    while (active_readers > 0) {
        printf("Writer %d: waiting for readers to exit\n", id);
        pthread_cond_wait(&writer_cond, &mutex);
    }
    pthread_mutex_unlock(&mutex);

    // Perform operations
    for (int i = 0; i < NUM_OPERATIONS; i++) {
        atomic_fetch_add(&shared_var, 100);
        printf("Writer %d: shared_var = %d\n", id, shared_var);
        usleep(1000);
    }

    printf("Writer %d exiting critical section\n", id);
    return NULL;
}

int main() {
    pthread_t reader_threads[NUM_READERS];
    pthread_t writer_threads[NUM_WRITERS];
    int reader_ids[NUM_READERS];
    int writer_ids[NUM_WRITERS];

    // Initialize IDs
