sem_t reader_mutex;     // Protects reader access
sem_t reader_count;     // Number of active readers
sem_t writer_ready;     // Writers wait here when no readers are active

// Condition variable for readers to wait when no writer is active
pthread_cond_t reader_cond = PTHREAD_COND_INITIALIZER;

// Function to check invariant: B must equal 2 * A
int invariant_holds(int a, int b) {
    return (b == 2 * a);
}

// Reader thread function
void* reader_thread(void *arg) {
    int id = *(int*)arg;
    printf("Reader %d: entering critical section\n", id);

    // Wait for writer to finish or for writer to be ready
    sem_wait(&reader_mutex);
    sem_wait(&reader_count);

    // Check invariant on every read
    if (!invariant_holds(A, B)) {
        printf("Reader %d: INVARIENT VIOLATED! A=%d, B=%d\n", id, A, B);
        sem_post(&reader_count);
        sem_post(&reader_mutex);
        return NULL;
    }

    printf("Reader %d: reading A=%d, B=%d (invariant holds)\n", id, A, B);

    // Simulate reading (do nothing, just verify)
    usleep(1000);

    // Exit section
    sem_post(&reader_count);
    sem_post(&reader_mutex);

    printf("Reader %d: exiting critical section\n", id);
    return NULL;
}

// Writer thread function
void* writer_thread(void *arg) {
    int id = *(int*)arg;
    printf("Writer %d: entering critical section\n", id);

    // Wait for all readers to exit
    sem_wait(&writer_mutex);

    // Simulate writing
    int new_A = rand() % 100;
    A = new_A;
    B = 2 * new_A;  // Enforce invariant

    printf("Writer %d: wrote A=%d, B=%d (invariant holds)\n", id, A, B);

    // Release writer mutex
    sem_post(&writer_mutex);

    printf("Writer %s: exiting critical section\n", id);
    return NULL;
}

int main() {
    pthread_t reader_threads[NUM_READERS];
    pthread_t writer_threads[NUM_WRITERS];

    // Initialize semaphores
    sem_init(&reader_mutex, 0, 1);
    sem_init(&reader_count, 0, 0);
    sem_init(&writer_mutex, 0, 1);
    sem_init(&writer_ready, 0, 0);

    // Start readers
    for (int i = 0; i < NUM_READERS; i++) {
        int *id = malloc(sizeof(int));
        *id = i;
        pthread_create(&reader_threads[i], NULL, reader_thread, id);
    }

    // Start writers
    for (int i = 0; i < NUM_WRITERS; i++) {
        int *id = malloc(sizeof(int));
        *id = i;
        pthread_create(&writer_threads[i], NULL, writer_thread, id);
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_READERS; i++) {
        pthread_join(reader_threads[i], NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_join(writer_threads[i], NULL);
    }

    printf("All threads finished. Final state: A=%d, B=%d\n", A, B);

    // Clean up
    sem_destroy(&reader_mutex);
    sem_destroy(&reader_count);
    sem_destroy(&writer_mutex);
    sem_destroy(&writer_ready);

    return 0;
}
