#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define N 10
#define NUM_THREADS 3

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int turn = 0;  // 0, 1, or 2: which thread should print next
int current_num = 1;

void* print_number(void* arg) {
    int tid = *(int*)arg;
    for (int i = 1; i <= N; i++) {
        pthread_mutex_lock(&mutex);
        while (turn != tid) {
            pthread_cond_wait(&cond, &mutex);
        }
        printf("Thread %d: %d\n", tid, current_num++);
        turn = (turn + 1) % NUM_THREADS;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int thread_ids[NUM_THREADS] = {0, 1, 2};

    // Create threads
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, print_number, &thread_ids[i]);
    }

    // Wait for all threads to finish
