```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define N 10
#define NUM_THREADS 3

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond0 = PTHREAD_COND_INITIALIZER;
pthread_cond_t cond1 = PTHREAD_COND_INITIALIZER;
pthread_cond_t cond2 = PTHREAD_COND_INITIALIZER;

int current = 1;
int turn = 0; // 0: Thread 0, 1: Thread 1, 2: Thread  2

void* print_thread(void* arg) {
    int id = *(int*)arg;
    printf("Thread %d: ", id);
    while (current <= N) {
        // Wait until it's this thread's turn
        pthread_mutex_lock(&mutex);
        while (turn != id) {
            pthread_cond_wait((id == 0) ? &cond0 : (id == 1) ? &cond1 : &cond2, &mutex);
        }
        // Print the number
        printf("%d ", current);
        current++;
        turn = (id + 1) % 3; // Next thread gets turn
        pthread_mutex_unlock(&mutex);

        // Signal the next thread
        if (id == 0) {
            pthread_cond_signal(&cond1);
        } else if (id == 1) {
            pthread_cond_signal(&cond2);
        } else { // id == 2
            pthread_cond_signal(&cond0);
        }
    }
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int ids[NUM_THREADS] = {0, 1, 2};

    // Create threads
    for (int i = 0; i < NUM_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, print_thread, &ids[i])) {
            perror("pthread_create");
            exit(1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    printf("\nDone.\n");
    return 0;
}
```

