pthread_mutex_t women_mutex = PTHREAD_MUTEX_INITIALIZER;

pthread_cond_t men_cond = PTHREAD_COND_INITIALIZER;
pthread_cond_t women_cond = PTHREAD_COND_INITIALIZER;

