    int id = *(int*)arg;
    printf("Man %d entering bathroom.\n", id);

    // Acquire mutex for men
    pthread_mutex_lock(&men_mutex);
    while (men_in_bathroom >= MAX_IN_BATHROOM) {
        printf("Man %d waiting for spot in bathroom.\n", id);
        pthread_cond_wait(&men_cond, &men_mutex);
