// Custom reusable barrier for N threads
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int count;        // number of threads waiting
    int n;             // total number of threads in barrier
    int reached;       // whether all threads have reached this barrier
} barrier_t;

// Initialize barrier
void barrier_init(barrier_t *b, int n) {
    b->n = n;
    b->count = 0;
    b->reached = 0;
    pthread_mutex_init(&b->mutex, NULL);
    pthread_cond_init(&b->cond, NULL);
}

// Wait at barrier: all threads must wait until all have arrived
void barrier_wait(barrier_t *b) {
    pthread_mutex_lock(&b->mutex);
    b->count++;
    if (b->count == b->n) {
        // All threads have arrived — signal all to proceed
        b->reached = 1;
        pthread_cond_broadcast(&b->cond);
    } else {
        // Wait for others to arrive
        while (!b->reached) {
            pthread_cond_wait(&b->cond, &b->mutex);
        }
    }
    pthread_mutex_unlock(&b); // Unlock after all have passed
}

// Destroy barrier
void barrier_destroy(barrier_t *b) {
    pthread_mutex_destroy(&b->mutex);
    pthread_cond_destroy(&b->cond);
}

