    // Synchronize at first barrier
    barrier_wait(barrier);

    printf("Thread %d: phase 1 complete, entering phase 2\n", id);

    // Phase 2: all threads do work
    sleep(1);

    printf("Thread %d: phase 2 complete\n", id);

    pthread_exit(NULL);
}

// Main function to run 4 threads with 2-phase barrier
int main() {
