        int a = rand() % 3;
        int b = rand() % 3;
        while (a == b) {
            b = rand() % 3;
        }

        // Assign the two items
        pthread_mutex_lock(&mutex);
        if (a == 0) tobacco = 1; else tobacco = 0;
        if (b == 0) paper =  1; else paper = 0;
        if (b == 1) matches = 1; else matches = 0;
        pthread_mutex_unlock(&mutex);

        // Wait a moment to simulate time
        usleep(100000); // 100ms

        // Increment round
        round++;
    }

    return NULL;
}

