// Shared array to store partial sums
int partial_sums[THREADS];

// Mutex to protect access to partial_sums
pthread_mutex_t sum_mutex = PTHREAD_MUTEX_INITIALIZER;

// Thread argument structure
typedef struct {
    int start;
    int end;
    int* partial_sum;
} thread_args_t;

// Function to compute partial sum for a segment
void* compute_partial_sum(void* arg) {
    thread_args_t* targs = (thread_args_t*)arg;
    int sum = 0;
    for (int i = targs->start; i < targs->end; i++) {
        sum += array[i];
    }
    targs->partial_sum[0] = sum; // Store in the first element of partial_sum
    return NULL;
}

int main() {
