    thread_args_t targs[THREADS];
    int segment_size = N / THREADS;
    int remainder = N % THREADS;

    for (int i = 0; i < THREADS; i++) {
        targs[i].start = i * segment_size + (i < remainder ? 0 : 0);
        targs[i].end = (i +  1) * segment_size + (i < remainder ? 1 : 0);
        targs[i].partial_sum = &partial_sums[i];
    }

    // Create threads
    pthread_t threads[THREADS];
    for (int i = 0; i < THREADS; i++) {
