    for (int i = 0; i < THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Aggregate partial sums in main thread with mutual exclusion
    int total_sum = 0;
    pthread_mutex_lock(&sum_mutex);
    for (int i = 0; i < THREADS; i++) {
