```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define NUM_PHILOSOPHERS 5
#define MAX_EATS 3

// Shared state: each philosopher has a left and right fork
pthread_mutex_t forks[NUM_PHILOSOPHERS];
pthread_mutex_t waiter_mutex; // protects the waiter's state
pthread_cond_t waiter_cond;   // condition for philosophers to wait on
int num_trying = 0;           // number of philosophers trying to pick up forks

void* philosopher(void* arg) {
    int id = *(int*)arg;
    int left_fork = id;
    int right_fork = (id + 1) % NUM_PHILOSOPHERS;

    printf("Philosopher %d is thinking.\n", id);

    for (int eat = 0; eat < MAX_EATS; eat++) {
        // Wait for waiter to allow entry (only 4 at a time)
        pthread_mutex_lock(&waiter_mutex);
        while (num_trying >= 4) {
            printf("Philosopher %d is waiting for waiter.\n", id);
            pthread_cond_wait(&waiter_cond, &waiter_mutex);
        }
        num_trying++;
        pthread_mutex_unlock(&waiter_mutex);

        // Pick up left fork first
        pthread_mutex_lock(&forks[left_fork]);
        printf("Philosopher %d picked up left fork.\n", id);

        pthread_mutex_lock(&forks[right_fork]);
        printf("Philosopher %d picked up right fork.\n", id);

        // Eat
        printf("Philosopher %d is eating.\n", id);
        usleep(100000); // Simulate eating

        // Release both forks
        pthread_mutex_unlock(&forks[right_fork]);
        pthread_mutex_unlock(&forks[left_fork]);

        // Wait for waiter to allow next attempt
        pthread_mutex_lock(&waiter_mutex);
        num_trying--;
        pthread_mutex_unlock(&waiter_mutex);

        // Wait a bit before next meal
        usleep(10); 
    }

    printf("Philosopher %d finished eating.\n", id);
    return NULL;
}

int main() {
    pthread_t threads[NUM_PHILOSOPHERS];
    int ids[NUM_PHILOSOPHERS];

    // Initialize forks and waiter
    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_mutex_init(&forks[i], NULL);
    }
    pthread_mutex_init(&waiter_mutex, NULL);
    pthread_cond_init(&waiter_cond, NULL);

    // Create philosopher threads
    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        ids[i] = i;
        pthread_create(&threads[i], NULL, philosopher, &ids[i]);
    }

    // Wait for all philosophers to finish
    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_mutex_destroy(&forks[i]);
    }
    pthread_mutex_destroy(&waiter_mutex);
    pthread_cond_destroy(&waiter_cond);

    printf("All philosophers finished. Resources cleaned up.\n");
    return 0;
}
```

---

**Correctness Analysis:**

- **Mutual Exclusion**: Each fork is protected by a mutex. When a philosopher holds a fork, no other thread can acquire it simultaneously. This ensures that only one philosopher can hold a given fork at a time [n].

- **Progress**: The waiter condition variable ensures that philosophers do not block indefinitely. When the number of trying philosophers drops below 4, the waiter signals others to proceed. This guarantees that if a philosopher is ready, it will eventually get a chance to pick up forks.

- **No Deadlock**: The arbitrator (waiter) limits concurrent attempts to 4. Since only 5 philosophers exist, and at most 4 can attempt to pick up forks, no philosopher is left waiting forever. The condition variable ensures that philosophers are not stuck in a circular wait [n].

- **No Lost Wakeups**: The condition variable is used with a mutex, and the waiter is only signaled when the number of trying philosophers drops below 4. The `pthread_cond_wait` function ensures that the waiter is not lost — it only wakes up when the condition is met and the mutex is released properly. The loop structure ensures that the waiter does not miss any wakeups.

- **Correct Fork Order**: Each philosopher picks up the left fork first, then the right fork (left = id, right = (id+1)%5), which avoids the classic deadlock scenario due to circular waiting.

