#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>

#define BUFFER_SIZE 5
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 2

sem_t buffer_empty;    // Initially BUFFER_SIZE (space available)
sem_t buffer_full;     // Initially 0 (items in buffer)
sem_t mutex;           // For mutual exclusion on buffer access

int buffer[BUFFER_SIZE];
int in = 0, out = 0;

void* producer(void *arg) {
    int item = 0;
    for (int i = 0; i < 10; i++) {
        // Wait for space in buffer
        sem_wait(&buffer_empty);
        // Critical section: access buffer
        mutex_lock(&mutex);
        buffer[in] = item;
        in = (in + 1) % BUFFER_SIZE;
        mutex_unlock(&mutex);
        printf("Producer produced item %d\n", item);
        item++;
        // Signal consumer that buffer has item
        sem_post(&buffer_full);
        usleep(10000); // Simulate work
    }
    return NULL;
}

void* consumer(void *arg) {
    int item;
    for (int i = 0; i < 10; i++) {
        // Wait for item in buffer
        sem_wait(&buffer_full);
        // Critical section: access buffer
        mutex_lock(&mutex);
        item = buffer[out];
        out = (out +  1) % BUFFER_SIZE;
        mutex_unlock(&mutex);
        printf("Consumer consumed item %d\n", item);
        // Signal producer that space is available
        sem_post(&buffer_empty);
        usleep(10000); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_t producer_threads[NUM_PRODUCERS];
    pthread_t consumer_threads[NUM_CONSUMERS];

    // Initialize semaphores
    sem_init(&buffer_empty, 0, BUFFER_SIZE);
    sem_init(&buffer_full, 0, 0);
    sem_init(&mutex, 0, 1);

    // Create producer threads
    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_create(&producer_threads[i], NULL, producer, NULL);
    }

    // Create consumer threads
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_create(&consumer_threads[i], NULL, consumer, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < NUM_PRODUCERS; i++) {
        pthread_join(producer_threads[i], NULL);
    }
    for (int i = 0; i < NUM_CONSUMERS; i++) {
        pthread_join(consumer_threads[i], NULL);
    }

    // Clean up semaphores
    sem_destroy(&buffer_empty);
    sem_destroy(&buffer_full);
    sem_destroy(&mutex);

    printf("Producer-consumer problem completed.\n");
    return 0;
}
